// Nothing else is required: no scanning, no UI, no flashing.

#pragma once

#include <array>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <stdexcept>
#include <string>
#include <vector>

namespace hid_v3 {

constexpr std::size_t REPORT_SIZE = 64;
constexpr std::uint8_t OUT_ID = 12;
constexpr std::uint8_t IN_ID = 13;
constexpr std::uint8_t FEATURE_ID = 14;
constexpr std::uint8_t VERSION = 3;
constexpr std::size_t MAX_PAYLOAD = 51;
constexpr std::size_t HEADER = 13;

constexpr std::uint8_t OPEN = 0x01;
constexpr std::uint8_t CLOSE = 0x02;
constexpr std::uint8_t HEARTBEAT = 0x03;
constexpr std::uint8_t BARRIER = 0x04;
constexpr std::uint8_t RELEASE = 0x05;
constexpr std::uint8_t STATUS = 0x06;
constexpr std::uint8_t STATUS_EXT = 0x07;
constexpr std::uint8_t SESSION_LIST = 0x08;
constexpr std::uint8_t BOOTLOADER = 0x09;
constexpr std::uint8_t KEY = 0x10;
constexpr std::uint8_t SNAPSHOT = 0x11;
constexpr std::uint8_t MOVE = 0x12;
constexpr std::uint8_t BUTTONS = 0x13;
constexpr std::uint8_t WHEEL = 0x14;
constexpr std::uint8_t EVENT = 0x7F;

class Error : public std::runtime_error {
public:
    explicit Error(const std::string& what) : std::runtime_error(what) {}
};

class ProtocolError : public std::runtime_error {
public:
    explicit ProtocolError(const std::string& what) : std::runtime_error(what) {}
};

inline std::uint16_t u16(const std::uint8_t* p) {
    return static_cast<std::uint16_t>(p[0] | (p[1] << 8));
}

inline std::uint32_t u32(const std::uint8_t* p) {
    return static_cast<std::uint32_t>(p[0]) | (static_cast<std::uint32_t>(p[1]) << 8) |
           (static_cast<std::uint32_t>(p[2]) << 16) | (static_cast<std::uint32_t>(p[3]) << 24);
}

inline void put16(std::uint8_t* p, std::uint16_t value) {
    p[0] = static_cast<std::uint8_t>(value & 0xFF);
    p[1] = static_cast<std::uint8_t>(value >> 8);
}

inline void put32(std::uint8_t* p, std::uint32_t value) {
    p[0] = static_cast<std::uint8_t>(value & 0xFF);
    p[1] = static_cast<std::uint8_t>((value >> 8) & 0xFF);
    p[2] = static_cast<std::uint8_t>((value >> 16) & 0xFF);
    p[3] = static_cast<std::uint8_t>((value >> 24) & 0xFF);
}

struct Feature {
    std::uint8_t board = 0;
    std::uint8_t major = 0;
    std::uint8_t minor = 0;
    std::uint8_t patch = 0;
    std::uint16_t lease_ms = 0;
    std::uint8_t poll_ms = 0;
    std::uint32_t capabilities = 0;

    bool supports_nkro() const { return (capabilities & 1u) != 0; }
    bool supports_consumer() const { return (capabilities & 2u) != 0; }
    bool supports_mouse() const { return (capabilities & 4u) != 0; }
    bool supports_sessions() const { return (capabilities & 8u) != 0; }
};

struct Status {
    std::uint32_t received = 0;
    std::uint32_t completed = 0;
    std::uint8_t pending = 0;
    std::uint16_t lease_ms = 0;
    std::uint16_t rx = 0;
    std::uint16_t tx = 0;
    std::uint16_t hid = 0;
    std::uint16_t failsafe = 0;
    std::array<std::uint8_t, 31> snapshot{};
};

struct StatusExt {
    std::uint32_t uptime_ms = 0;
    std::uint16_t late_max_us = 0;
    std::uint8_t out_depth = 0;
    std::uint8_t rx_depth = 0;
    std::uint8_t tx_depth = 0;
    std::uint8_t sessions = 0;
    std::uint8_t last_fault = 0;
    bool has_fault = false;
    std::uint32_t last_fault_age_ms = 0;
    std::uint8_t reset_reason = 0;
    std::uint16_t boot_count = 0;
    std::uint32_t build = 0;
};

struct SessionInfo {
    std::uint16_t id = 0;
    std::uint16_t lease_ms = 0;
    std::uint8_t held = 0;
    std::uint8_t flags = 0;
};

struct Reply {
    std::uint8_t opcode = 0;
    std::uint32_t sequence = 0;
    std::vector<std::uint8_t> payload;
};

class Transport {
public:
    virtual ~Transport() = default;
    virtual bool feature(std::array<std::uint8_t, REPORT_SIZE>& report) = 0;
    virtual void write(const std::array<std::uint8_t, REPORT_SIZE>& report) = 0;
    virtual bool read(std::array<std::uint8_t, REPORT_SIZE>& report, int timeout_ms) = 0;
};

inline std::string fault_text(std::uint8_t code) {
    switch (code) {
        case 1: return "framing";
        case 2: return "busy (same session id, or eight owners already open)";
        case 3: return "invalid input";
        case 5: return "lease expired";
        case 6: return "HID send failed";
        case 7: return "USB disconnect";
        case 8: return "overflow or stale output";
        case 9: return "duplicate sequence";
        case 10: return "sequence gap";
        default: return "unknown";
    }
}

class Client {
public:
    Client(Transport& transport, std::uint32_t session)
        : transport_(transport), session_(session == 0 ? 1 : session) {}

    Feature verify() {
        std::array<std::uint8_t, REPORT_SIZE> report{};
        if (!transport_.feature(report) || report[0] != FEATURE_ID) {
            throw ProtocolError("no Feature 14 reply");
        }
        if (std::memcmp(&report[1], "FMT3", 4) != 0 || report[5] != VERSION) {
            throw ProtocolError("Feature 14 is not protocol 3");
        }
        feature_.board = report[6];
        feature_.major = report[7];
        feature_.minor = report[8];
        feature_.patch = report[9];
        feature_.lease_ms = u16(&report[10]);
        feature_.poll_ms = report[14];
        feature_.capabilities = u32(&report[15]);
        return feature_;
    }

    void open() { command(OPEN, {}, true); }
    void close() { command(CLOSE, {}, true); }

    void heartbeat(std::uint64_t now_ms) {
        command(HEARTBEAT, {}, false);
        last_heartbeat_ms_ = now_ms;
    }

    void maybe_heartbeat(std::uint64_t now_ms, std::uint64_t interval_ms = 500) {
        if (now_ms - last_heartbeat_ms_ >= interval_ms) {
            heartbeat(now_ms);
        }
    }

    Status status() {
        Reply reply = command(STATUS, {}, true);
        if (reply.payload.size() != 51 || reply.payload[0] != 0) {
            throw ProtocolError("bad STATUS payload");
        }
        const std::uint8_t* p = reply.payload.data();
        Status out;
        out.received = u32(&p[1]);
        out.completed = u32(&p[5]);
        out.pending = p[9];
        out.lease_ms = u16(&p[10]);
        out.rx = u16(&p[12]);
        out.tx = u16(&p[14]);
        out.hid = u16(&p[16]);
        out.failsafe = u16(&p[18]);
        std::memcpy(out.snapshot.data(), &p[20], 31);
        return out;
    }

    StatusExt status_ext() {
        Reply reply = command(STATUS_EXT, {}, true);
        if (reply.payload.size() != 23 || reply.payload[0] != 0) {
            throw ProtocolError("bad STATUS_EXT payload");
        }
        const std::uint8_t* p = reply.payload.data();
        StatusExt out;
        out.uptime_ms = u32(&p[1]);
        out.late_max_us = u16(&p[5]);
        out.out_depth = p[7];
        out.rx_depth = p[8];
        out.tx_depth = p[9];
        out.sessions = p[10];
        out.last_fault = p[11];
        out.last_fault_age_ms = u32(&p[12]);
        out.has_fault = out.last_fault_age_ms != 0xFFFFFFFFu;
        out.reset_reason = p[16];
        out.boot_count = u16(&p[17]);
        out.build = u32(&p[19]);
        return out;
    }

    std::vector<SessionInfo> sessions() {
        Reply reply = command(SESSION_LIST, {}, true);
        if (reply.payload.size() != 48) {
            throw ProtocolError("bad SESSION_LIST payload");
        }
        std::vector<SessionInfo> out;
        for (std::size_t index = 0; index < 8; ++index) {
            const std::uint8_t* entry = &reply.payload[index * 6];
            const std::uint16_t id = u16(entry);
            if (id != 0) {
                out.push_back(SessionInfo{id, u16(entry + 2), entry[4], entry[5]});
            }
        }
        return out;
    }

    void barrier() { command(BARRIER, {}, true); }
    void release_all() { command(RELEASE, {}, true); }
    void bootloader() { command(BOOTLOADER, {}, true); }

    void key(std::uint16_t page, std::uint16_t usage, bool down) {
        command(KEY, {static_cast<std::uint8_t>(page & 0xFF),
                      static_cast<std::uint8_t>(page >> 8),
                      static_cast<std::uint8_t>(usage & 0xFF),
                      static_cast<std::uint8_t>(usage >> 8),
                      static_cast<std::uint8_t>(down ? 1 : 0)},
                false);
    }

    void snapshot(const std::array<std::uint8_t, 31>& state) {
        command(SNAPSHOT,
                std::vector<std::uint8_t>(state.begin(), state.end()), false);
    }

    void mouse_move(std::int16_t dx, std::int16_t dy) {
        if (dx < -1024 || dx > 1024 || dy < -1024 || dy > 1024) {
            throw std::invalid_argument("mouse move is limited to +/-1024 per axis");
        }
        const auto ux = static_cast<std::uint16_t>(dx);
        const auto uy = static_cast<std::uint16_t>(dy);
        command(MOVE, {static_cast<std::uint8_t>(ux & 0xFF),
                       static_cast<std::uint8_t>(ux >> 8),
                       static_cast<std::uint8_t>(uy & 0xFF),
                       static_cast<std::uint8_t>(uy >> 8)},
                false);
    }

    void buttons(std::uint8_t mask) {
        if ((mask & 0xE0u) != 0) {
            throw std::invalid_argument("buttons are bits 0-4");
        }
        command(BUTTONS, {mask}, false);
    }

    void wheel(std::int16_t vertical, std::int16_t horizontal) {
        if (vertical < -1024 || vertical > 1024 || horizontal < -1024 || horizontal > 1024) {
            throw std::invalid_argument("wheel is limited to +/-1024 per axis");
        }
        const auto uv = static_cast<std::uint16_t>(vertical);
        const auto uh = static_cast<std::uint16_t>(horizontal);
        command(WHEEL, {static_cast<std::uint8_t>(uv & 0xFF),
                        static_cast<std::uint8_t>(uv >> 8),
                        static_cast<std::uint8_t>(uh & 0xFF),
                        static_cast<std::uint8_t>(uh >> 8)},
                false);
    }

    std::uint32_t session() const { return session_; }

private:
    Reply command(std::uint8_t opcode, const std::vector<std::uint8_t>& payload, bool reply) {
        if (payload.size() > MAX_PAYLOAD) {
            throw std::invalid_argument("payload is at most 51 bytes");
        }
        if (sequence_ == 0xFFFFFFFFu) {
            throw Error("sequence exhausted; open a new session");
        }
        const std::uint32_t sequence = ++sequence_;
        std::array<std::uint8_t, REPORT_SIZE> report{};
        report[0] = OUT_ID;
        report[1] = VERSION;
        report[2] = opcode;
        report[3] = static_cast<std::uint8_t>(payload.size());
        put32(&report[5], session_);
        put32(&report[9], sequence);
        if (!payload.empty()) {
            std::memcpy(&report[13], payload.data(), payload.size());
        }
        transport_.write(report);
        if (!reply) {
            return Reply{};
        }
        return await(opcode, sequence, 1000);
    }

    Reply await(std::uint8_t opcode, std::uint32_t sequence, int timeout_ms) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(timeout_ms);
        while (std::chrono::steady_clock::now() < deadline) {
            std::array<std::uint8_t, REPORT_SIZE> report{};
            if (!transport_.read(report, 50)) {
                continue;
            }
            if (report[0] != IN_ID || report[1] != VERSION || report[4] != 0) {
                throw ProtocolError("bad input report framing");
            }
            const std::uint8_t length = report[3];
            if (length > MAX_PAYLOAD) {
                throw ProtocolError("payload longer than 51 bytes");
            }
            if (u32(&report[5]) != session_) {
                continue;
            }
            const std::uint8_t got_opcode = report[2];
            const std::uint32_t got_sequence = u32(&report[9]);
            if (got_opcode == EVENT) {
                throw Error("device event: " + fault_text(report[13]));
            }
            if (got_opcode != (opcode | 0x80) || got_sequence != sequence) {
                continue;
            }
            Reply reply;
            reply.opcode = got_opcode;
            reply.sequence = got_sequence;
            reply.payload.assign(&report[13], &report[13] + length);
            if (reply.payload.empty()) {
                throw ProtocolError("empty control reply");
            }
            if (opcode == SESSION_LIST) {
                return reply;
            }
            if (reply.payload[0] != 0) {
                throw Error(fault_text(reply.payload[0]) + " (code " +
                            std::to_string(reply.payload[0]) + ")");
            }
            return reply;
        }
        throw Error("control reply timed out");
    }

    Transport& transport_;
    std::uint32_t session_;
    std::uint32_t sequence_ = 0;
    std::uint64_t last_heartbeat_ms_ = 0;
    Feature feature_{};
};

}  // namespace hid_v3
